      return { kind: "reject", message: "复盘最多 5000 字" };
    return {
      kind: "commit",
      state: "done",
      fields: { ...task.fields, review: input.review.trim() },
    };
  },
};

export default {
  describe: () => workflow.definition,
  decide: (data: {
    task: Parameters<typeof workflow.decide>[0];
    action: string;
    input: Record<string, string>;
  }) => workflow.decide(data.task, data.action, data.input),
};
